import os
import re

# Search all files for any club-related patterns
for root, dirs, files in os.walk('.'):
    for f in files:
        if f.endswith(('.md', '.csv', '.json')):
            path = os.path.join(root, f)
            try:
                with open(path, 'r') as file:
                    content = file.read()
                    # Look for patterns like link_to_club, club_id, etc.
                    matches = re.findall(r'[a-zA-Z_]+[Cc]lub|[Cc]lub[a-zA-Z_]*|link_to_[a-zA-Z_]+', content)
                    if matches:
                        print(f'=== {path} ===')
                        unique_matches = set(matches)
                        for m in list(unique_matches)[:20]:
                            print(m)
            except Exception as e:
                pass

